INSERT INTO Step (id, text, number, optional, recipeId) VALUES (1, 'Na cibuli opečieme nakrájanú klobásu.', 1, false, 1);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (2, 'Pridáme kapustu, zalejeme vodou a varíme hodinu.', 2, false, 1);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (3, 'Primiešame namočené huby.', 3, true, 1);
