INSERT INTO Step (id, text, number, optional, recipeId) VALUES (6, 'Zemiaky nastrúhame a s múkou vypracujeme cesto.', 1, false, 3);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (7, 'Halušky hádžeme do vriacej osolenej vody.', 2, false, 3);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (8, 'Zmiešame s bryndzou a posypeme opečenou slaninou.', 3, false, 3);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (9, 'Mäso opečieme, pridáme cibuľu a papriku.', 1, false, 4);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (10, 'Podlejeme vodou a dusíme do mäkka, zjemníme smotanou.', 2, false, 4);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (11, 'Uvaríme cestoviny, losos opečieme so špenátom a zalejeme smotanou.', 1, false, 5);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (12, 'Vymiešame hladké cesto a necháme odpočinúť.', 1, false, 6);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (13, 'Pečieme na rozpálenej panvici z oboch strán.', 2, false, 6);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (14, 'Šošovicu uvaríme, scedíme a zmiešame s cibuľou.', 1, false, 8);
