INSERT INTO Step (id, text, number, optional, recipeId) VALUES (15, 'Cibuľu speníme dozlatista.', 1, false, 10);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (16, 'Pridáme na kocky nakrájané mäso a opečieme ho zo všetkých strán.', 2, false, 10);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (17, 'Zaprášime paprikou, pridáme rascu a podlejeme vodou.', 3, false, 10);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (18, 'Na konci pridáme feferónku pre pikantnú chuť.', 4, true, 10);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (19, 'Dusíme dve hodiny do mäkka, na záver pridáme cesnak.', 5, false, 10);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (20, 'Na masle speníme cibuľu a opražíme huby.', 1, false, 11);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (21, 'Pridáme ryžu a krátko ju opražíme.', 2, false, 11);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (22, 'Podlejeme vínom a necháme ho odpariť.', 3, true, 11);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (23, 'Postupne prilievame vývar a miešame, kým ryža nezmäkne.', 4, false, 11);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (24, 'Vmiešame parmezán a maslo.', 5, false, 11);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (25, 'Mäso opečieme s cibuľou a paprikou.', 1, false, 12);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (26, 'Pridáme kapustu, podlejeme a dusíme do mäkka.', 2, false, 12);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (27, 'Zahustíme smotanou a krátko povaríme.', 3, false, 12);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (28, 'Uvaríme špagety al dente.', 1, false, 13);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (29, 'Slaninu opečieme do chrumkava.', 2, false, 13);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (30, 'Vajcia rozšľaháme s parmezánom a vmiešame do horúcich cestovín mimo ohňa.', 3, false, 13);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (31, 'Zemiaky nastrúhame a vytlačíme z nich vodu.', 1, false, 14);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (32, 'Zmiešame s vajcom, múkou, cesnakom a majoránom.', 2, false, 14);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (33, 'Smažíme na rozpálenom oleji do zlatista.', 3, false, 14);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (34, 'Fazuľu namočíme cez noc.', 1, false, 15);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (35, 'Uvaríme ju s údeným mäsom, mrkvou a bobkovým listom.', 2, false, 15);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (36, 'Zahustíme smotanou a dochutíme octom.', 3, false, 15);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (37, 'Na masle speníme cibuľu.', 1, false, 16);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (38, 'Pridáme vajcia a za stáleho miešania ich necháme zatiahnuť.', 2, false, 16);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (39, 'Z droždia, cukru a vlažného mlieka pripravíme kvások.', 1, false, 17);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (40, 'Vymiešame cesto a necháme ho vykysnúť.', 2, false, 17);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (41, 'Pečieme na lievanečníku a podávame s čučoriedkami.', 3, false, 17);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (42, 'Zemiaky uvaríme v osolenej vode s rascou.', 1, false, 19);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (43, 'Pridáme roztlačený cesnak a podávame so syrom a krutónmi.', 2, false, 19);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (44, 'Zeleninu nakrájame na väčšie kúsky.', 1, false, 20);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (45, 'Pridáme olivy a fetu, polejeme olejom a posypeme oreganom.', 2, false, 20);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (46, 'Čokoládu rozpustíme s maslom.', 1, false, 21);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (47, 'Vajcia vyšľaháme s cukrom do peny.', 2, false, 21);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (48, 'Spojíme s čokoládou a jemne vmiešame múku.', 3, false, 21);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (49, 'Pečieme 30 minút pri 170 °C.', 4, false, 21);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (50, 'Ozdobíme malinami.', 5, true, 21);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (51, 'Chlieb opečieme.', 1, false, 22);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (52, 'Avokádo roztlačíme s citrónovou šťavou, natrieme na chlieb a osolíme.', 2, false, 22);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (53, 'Cibuľu so zázvorom speníme.', 1, false, 23);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (54, 'Pridáme tekvicu, zalejeme vodou a varíme 20 minút.', 2, false, 23);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (55, 'Rozmixujeme s kokosovým mliekom.', 3, false, 23);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (56, 'Oriešky opražíme nasucho.', 1, false, 24);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (57, 'Bazalku, oriešky, cesnak, parmezán a olej rozmixujeme na pesto.', 2, false, 24);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (58, 'Zmiešame s uvarenými cestovinami.', 3, false, 24);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (59, 'Cuketu nastrúhame, osolíme a vytlačíme.', 1, false, 25);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (60, 'Zmiešame s vajcami, múkou a cesnakom.', 2, false, 25);
INSERT INTO Step (id, text, number, optional, recipeId) VALUES (61, 'Opečieme na panvici a podávame s jogurtom.', 3, false, 25);
